def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    elif not isinstance(value, timedelta):
        raise ValueError("The input value must be a timedelta")
    else:
        years, remain = divmod(value.days, 365)
        months, remain = divmod(remain, 30)
        days = remain
        hours = value.seconds // 3600
        minutes = (value.seconds // 60) % 60
        seconds = value.seconds % 60
        if years:
            return '{0} years, {1} months, {2} days, {3} hours, {4} minutes, {5} seconds'.format(
                years, months, days, hours, minutes, seconds)
        elif months:
            return '{0} months, {1} days, {2} hours, {3} minutes, {4} seconds'.format(
                months, days, hours, minutes, seconds)
        elif days:
            return '{0} days, {1} hours, {2} minutes, {3} seconds'.format(
                days, hours, minutes, seconds)
        elif hours:
            return '{0} hours, {1} minutes, {2} seconds'.format(
                hours, minutes, seconds)
        elif minutes:
            return '{0} minutes, {1} seconds'.format(
                minutes, seconds)
        else:
            return '{0} seconds'.format(seconds)

