from neo4j.exceptions import TransactionExpiredError

def unit_of_work(metadata=None, timeout=None):
    def decorator(transaction_func):
        def wrapper(tx):
            if metadata is not None:
                tx.metadata = metadata

            if timeout is not None:
                transaction = tx.ensure_transaction()
                try:
                    transaction.run("CALL Neo4jTx.currentThread().setDefaultTimeout({timeout})".format(timeout=timeout))

                    try:
                        return transaction_func(tx)
                    except TransactionExpiredError:
                        raise TransactionExpiredError("Transaction expired before the function has been completed.")
                finally:
                    transaction.close()
            else:
                return transaction_func(tx)

        return wrapper
    return decorator

from neo4j import graphdb

def unit_of_work(metadata=None, timeout: float | None = None):
    def decorator(func):
        def wrapper(tx):
            try:
                tx.autocommit = False
                result = func(tx)
                tx.commit()
                return result
            except graphdb.DatabaseError as e:
                tx.abort()
                raise e
            except Exception as e:
                tx.abort()
                raise e

        return wrapper

    return decorator

