def xargs(cmd: tuple[str, ...], varargs: Sequence[str], *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    import sys

    if len(varargs) == 0:
        raise ValueError("No arguments to be passed to xargs")

    if color and not sys.stdout.isatty():
        raise ValueError("Color option is only available on interactive terminals")

    partitions = {}
    for arg in varargs:
        if len(arg) > _max_length:
            raise ValueError(f"Argument '{arg}' exceeds maximum length {_max_length}")

        if arg in partitions:
            partitions[arg][1] += 1
        else:
            partitions[arg] = [0, 1]

        while partitions[arg][0] >= partitions[arg][1]:
            partitions.pop(arg)

            if len(partitions) < target_concurrency:
                new_arg = sys.stdin.readline().strip()
                if new_arg == '':
                    break

                partitions[new_arg] = [0, 1]

            if len(partitions) == 0:
                return (0, b'')

    stdout = b''

    for arg in partitions:
        for _ in range(partitions[arg][0] + 1):
            print(arg, end='', file=sys.stdout, flush=False)

        stdout += arg.encode('utf-8')

    sys.stdout.flush()

    return (len(partitions), stdout)

