@classmethod
    def extostr(cls, e, max_level=30, max_path_level=5):
        """
        Format an exception.
        :param e: Any exception instance.
        :type e: Exception
        :param max_level: Maximum call stack level (default 30)
        :type max_level: int
        :param max_path_level: Maximum path level (default 5)
        :type max_path_level: int
        :return The exception readable string
        :rtype str
        """
        def format_exception(e, level=0):
            if level >= max_level:
                return f'[...]\n'
            parts = [f'{cls.__name__}: {str(e)}']
            for tb in traceback.extract_tb(e.__traceback__):
                frame = tb[0]
                if level >= max_path_level:
                    break
                parts.append(f'{frame.function} in {frame.filename} at {frame.lineno}')
                parts.append(format_exception(e.__cause__, level + 1))
            return '\n'.join(parts)

        return format_exception(e)

