def integral(bins, edges):
    if bins is None or edges is None:
        raise ValueError("Bins and edges cannot be None")

    if not bins:
        return 0

    if not edges:
        raise ValueError("Edges must be a non-empty list")

    if len(bins) != len(edges) - 1:
        raise ValueError("Number of bins must match number of edges minus one")

    # Compute the integral of each bin
    integral_values = [max(0, (edges[i + 1] - edges[i]) * bins[i]) for i in range(len(bins))]

    # Sum the integral values to get the total integral
    total_integral = sum(integral_values)

    return total_integral

