    if not isinstance(edges, (list, tuple)):
        raise TypeError("edges must be a list or tuple")

    if not all(isinstance(x, float) for x in bins):
        raise TypeError("bins must be a list of floats")

    if not all(isinstance(x, float) for x in edges):
        raise TypeError("edges must be a list of floats")

    if len(bins) != len(edges) - 1:
        raise ValueError("bins must have one more element than edges")

    for i in range(len(bins) - 1):
        integral_result += bins[i+1] - bins[i]

    return integral_result

def integral(bins, edges):
    """
    Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`histogram` description.
    """
    if not isinstance(bins, (list, np.ndarray)) or not isinstance(edges, (list, np.ndarray)):
        raise TypeError("Both bins and edges must be lists or NumPy arrays.")

    if not all(isinstance(e, (float, int)) for e in edges):
        raise TypeError("All elements in edges must be numeric.")

    if len(bins) < 2 or len(edges) < 2:
        raise ValueError("Bins and edges must contain at least 2 elements.")

    if edges[0] > edges[-1]:
        raise ValueError("Edges must be increasing.")

    if np.any(bins[:-1] >= bins[1:]):
        raise ValueError("Bins must be strictly increasing.")

    if np.any(edges[:-1] >= edges[1:]):
        raise ValueError("Edges must be strictly increasing.")

    # Calculate integral by summing the differences between bins and edges
    integral_values = np.cumsum(bins[1:] - bins[:-1])

    return integral_values, edges

