    def deep_copy(sub_dict):
        res = {}
        for k, v in sub_dict.items():
            if isinstance(v, dict):
                res[k] = deep_copy(v)
            else:
                res[k] = v
        return res

    def recurse(d1, d2, path=[], level=level):
        if level == 0:
            return
        if isinstance(d1, dict) and isinstance(d2, dict):
            result = {}
            for key in d1:
                if key not in d2:
                    result[key] = d1[key]
                elif isinstance(d1[key], dict) and isinstance(d2[key], dict):
                    result[key] = recurse(d1[key], d2[key], path + [key], level - 1)
            return deep_copy(result)
        elif isinstance(d1, list):
            result = []
            for item in d1:
                if item not in d2:
                    result.append(item)
            return result
        elif isinstance(d1, set):
            return list(d1 - d2)
        elif not isinstance(d1, (dict, list, set)):
            return [d1] if d1 != d2 else []

    return recurse(d1, d2, [], level)

