) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    from collections import abc

    def cast_param_value(param, param_style):
        if isinstance(param, abc.Mapping):
            return {p: cast_param_value(v, param_style) for p, v in param.items()}
        else:
            return param

    def cast_params(params, param_style):
        if isinstance(params, abc.Mapping):
            return {k: cast_param_value(v, param_style) for k, v in params.items()}
        elif isinstance(params, abc.Sequence):
            return [cast_param_value(v, param_style) for v in params]
