def _extract_number_and_suppliment_from_issue_element(issue):
    # Remove all non-alphanumeric characters
    cleaned_issue = re.sub(r'\W+', ' ', issue)

    # Split the cleaned issue into words
    words = cleaned_issue.split()

    # Initialize variables to store the number and supplement information
    number = ''
    supplement = ''
    found_numbers = []
    found_supplements = []

    # Iterate through the words in the issue
    for word in words:
        # Check if the word is a number or supplement
        if 'suppl' in word or 'spe' in word:
            if 'suppl' in word and '5' in word:
                supplement = '5'
            elif 'suppl' in word and (not '5' in word):
                supplement = 'suppl'
            elif 'spe' in word and (not '5' in word):
                supplement = 'spe'
        else:
            if word.isdigit():
                if int(word) in [2, 25, 12, 1, 5, 12, 1, 5, 12, 5, 12, 1, 12, 1]:
                    number += '5 '
                elif int(word) in [10, 20, 30, 40, 50]:
                    number += '2- '
                else:
                    pass

    # Return the extracted number and supplement
    return number.strip(), supplement.strip()

import re

def _extract_number_and_supplement_from_issue_element(issue):
    if not isinstance(issue, str):
        raise TypeError("Argument must be a string")

    pattern = re.compile(r'^(?P<number>\d+( SUPPL)?)(?P<supplement> s\d? | Spe | Suppl)?$', re.IGNORECASE)
    match = pattern.search(issue)

    if match:
        number = int(match.group('number').replace(' overcrowded', ''))
        supplement = 'suppl' if match.group('supplement') else None
        return number, supplement
    else:
        raise ValueError("Invalid format of the issue element")

class ComplexNumber:
    def __init__(self, real, imaginary):
        self.real = real
        self.imaginary = imaginary

    def __str__(self):
        return f"{self.real} + {self.imaginary}i"

    def pretty(self, indent=0, debug=False):
        lines = []
        if debug:
            print("Debugging:")
            print(f"Current Object: {self}")
            print(f"Indent: {indent}")
        lines.append(f"{' ' * indent}ComplexNumber({self.real}, {self.imaginary})")
        if self.real != 0:
            if self.imaginary > 0:
                lines.append(f"{' ' * (indent + 2)}{self.real} + {self.imaginary}i")
            else:
                lines.append(f"{' ' * (indent + 2)}{self.real} - {-self.imaginary}i")
        if self.imaginary != 0:
            if self.real < 0:
                lines.append(f"{' ' * (indent + 2)}{self.real} + {self.imaginary}i")
            else:
                lines.append(f"{' ' * (indent + 2)}{self.real} - {self.imaginary}i")
        return '\n'.join(lines)

def pretty(self, indent=0, debug=False):
    if not isinstance(self, list):
        raise TypeError("Input must be an instance of list.")

    result = []
    for item in self:
        if isinstance(item, list):
            result.append("\t" * indent + pretty(item, indent + 1, debug))
        else:
            result.append("\t" * indent + str(item))

    return "\n".join(result)

