import os

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    try:
        # Create the subprocess object based on the given parameters
        subprocess_object = subprocess.Popen(
            commands,
            args=args,
            cwd=cwd,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE if not hide_stderr else subprocess.DEVNULL,
            text=True,
            env=env
        )
        # Wait for the command to finish and capture its output
        stdout, stderr = subprocess_object.communicate()
        if subprocess_object.returncode != 0:
            if verbose:
                print(f"Command failed with error: {stderr}")
            return None, stderr
        else:
            return stdout, None
    except Exception as e:
        if verbose:
            print(f"An error occurred: {e}")
        return None, str(e)

