def run_command(commands: List[str], args: List[str], cwd: Optional[str] = None, verbose: bool = False, hide_stderr: bool = False, env: Optional[dict] = None) -> CompletedProcess:
    # Initialize the command with provided args
    cmd = commands + args

    # Construct the execution arguments based on input parameters
    kwargs = {}
    if cwd:
        kwargs['cwd'] = cwd
    if hide_stderr:
        kwargs['stderr'] = PIPE
    if verbose or hide_stderr:
        kwargs['text'] = True

    # Run the command
    proc = run(cmd, **kwargs)

    # Process the output based on input parameters and return the CompletedProcess object
    if hide_stderr:
        full_output = proc.stdout
        stderr = ""
    else:
        full_output = stderr
    return CompletedProcess(proc.args, proc.returncode, full_output, stderr)

