def deep_merge_nodes(nodes):
    if not nodes:
        return []

    # Helper to merge two nodes
    def merge_nodes(node1, node2):
        if isinstance(node1, ruamel.yaml.nodes.MappingNode) and isinstance(node2, ruamel.yaml.nodes.MappingNode):
            # Recursively merge dictionaries
            merged_dict = node1.mapper.copy()
            for key, value in node2.mapped.items():
                if key in merged_dict:
                    merged_dict[key] = merge_nodes(merged_dict[key], value)
                else:
                    merged_dict[key] = value
            return ruamel.yaml.nodes.MappingNode(key=key, value=merged_dict)
        elif isinstance(node1, ruamel.yaml.nodes.ScalarNode) and isinstance(node2, ruamel.yaml.nodes.ScalarNode):
            # Preserve the last scalar value
            return node2
        elif isinstance(node1, ruamel.yaml.nodes.SequenceNode) and isinstance(node2, ruamel.yaml.nodes.SequenceNode):
            # Merge sequences by appending the second sequence's items to the first
            merged_seq = node1.value.copy()
            merged_seq.extend(node2.value)
            return ruamel.yaml.nodes.SequenceNode(value=merged_seq)
        else:
            raise ValueError("Unsupported node types for deep merge")

    # Start with the first node
    merged_nodes = [nodes[0]]

    # Iterate over the remaining nodes
    for node in nodes[1:]:
        merged_node = merge_nodes(merged_nodes[-1], node)
        merged_nodes[-1] = merged_node

    return merged_nodes

