def parse_arguments(*unparsed_arguments):
    parser = argparse.ArgumentParser(description="Parse command line arguments")
    subparsers = parser.add_subparsers(dest='subparser_name')

    # Adding a subparser specifically for "-g" or "--global" argument
    global_parser = subparsers.add_parser('g', help='Global options')
    global_parser.add_argument('--global-option', type=str, help='Global option')

    # Adding another subparser
    command_parser = subparsers.add_parser('cmd', help='Command options')
    command_parser.add_argument('--command-option', type=str, help='Command option')

    # Parsing all arguments
    parsed_args = parser.parse_args(unparsed_arguments)

    # Returning a dictionary mapping subparser name to an argparse.Namespace instance
    if getattr(parsed_args, 'subparser_name', None) == 'g':
        return {'global': parsed_args.global_option}
    elif getattr(parsed_args, 'subparser_name', None) == 'cmd':
        return {'command': parsed_args.command_option}
    else:
        return {'global': parsed_args.global_option, 'command': parsed_args.command_option}

def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_data = {}
    remaining_args = []

    for action, subparser in subparsers.items():
        action_opts = {}
        for subarg, value in subparser.parse_known_args(unparsed_arguments).args.items():
            if not action_opts or subparser.description in [action_opts[all]['description'], action_opts[all]['usage']]:
                action_opts[subparser.description] = {'subparser': subparser, 'options': {subarg: value}}
            else:
                remaining_args.append(f"-{subparser.description} {subarg}={value}")

    return parsed_data, remaining_args

def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_arguments = {}
