    for subparser in subparsers:
        try:
            # Attempt to parse the Arguments assigned to the subt.Parser
            result = subparser.parse_args(unparsed_arguments)
            parsed_arguments[subparser.name] = result
        except Exception as e:
            # Log any parsing exceptions and move on to the next subparser
            print(f"Error parsing arguments for subparser '{subparser.name}': {e}")

    # Move any remaining arguments to the remaining_arguments list (in the order they appeared)
    remaining_arguments = unparsed_arguments[len(parsed_arguments):]

    return parsed_arguments, remaining_arguments

def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_results = {}
    remaining_args = []

    for parser in subparsers.values():
        args, left_over = parser.parse_known_args(unparsed_arguments)
        if args:
            parsed_results[parser.name] = args
        remaining_args.extend(left_over)

    return parsed_results, remaining_args

def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_arguments = {}
    remaining_arguments = []

    for subparser in subparsers.values():
        try:
            result = subparser.parse_args(unparsed_arguments, namespace=parsed_arguments[subparser.name])
            parsed_arguments[subparser.name].update(vars(result))
        except (Exception, SystemExit) as e:
            print(f"Failed to parse {subparser.name} arguments: {e}")

    for argument in unparsed_arguments:
        if argument not in parsed_arguments.values():
            remaining_arguments.append(argument)

    return parsed_arguments, remaining_arguments

