import re

def size_to_bytes(size: str) -> int:
    # Regular expression to match the file size and the unit (K, M, G, T)
    match = re.search(r'(\d+)([KMGT]?)', size, re.IGNORECASE)
    if not match:
        raise ValueError("Invalid file size format")

    # Extracted value and unit
    value, unit = match.groups()

    # Convert value to integer
    value = int(value)

    # Convert to bytes based on the unit
    if unit == 'K':
        return value * 1024
    elif unit == 'M':
        return value * 1024 * 1024
    elif unit == 'G':
        return value * 1024 * 1024 * 1024
    elif unit == 'T':
        return value * 1024 * 1024 * 1024 * 1024
    else:
        # Return the original value if the unit is not recognized
        return value

