def size_to_bytes(size: str) -> int:
    unit = re.search(r'\D+$', size).group(0).lower()
    if unit not in ['k', 'm', 'g']:
        raise ValueError("Unknown unit. Supported units are 'K', 'M', 'G'")

    numeric_part = re.search(r'\d+', size).group(0)
    numeric_value = int(numeric_part)

    if unit == 'k':
        return numeric_value * 1024
    elif unit == 'm':
        return numeric_value * 1024 * 1024
    elif unit == 'g':
        return numeric_value * 1024 * 1024 * 1024

