    import os

    # Check if provided paths are valid
    if not os.path.exists(path_name):
        if verbose:
            print(f"Error: Path does not exist ({path_name}).")
        return True

    # Expand the path name to an absolute path
    abs_path_name = os.path.abspath(path_name)

    if verbose:
        print(f"Processing: {abs_path_name}")

    # If the directory is not empty, check its contents
    if os.path.isdir(abs_path_name):
        contents = os.listdir(abs_path_name)
        for item in contents:
            item_path = os.path.join(abs_path_name, item)
            processed.add(item_path)

            if was_processed(processed, item_path, verbose):
                return True

    # If the file is not in the set and the directory is empty, add it
    elif abs_path_name not in processed:
        processed.add(abs_path_name)
        return False

    return True

