        return alphabet[0]

    while number > 0:
        remainder = number % len(alphabet)
        output = alphabet[remainder] + output
        number //= len(alphabet)

    if max(len(output) for output in (number_to_string(num, alphabet) for num in range(1000))) != len(output):
