def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if number < 0 or number >= len(alphabet):
        raise ValueError("Number out of bounds for the alphabet")

    result = []

    if padding is not None:
        result = [str(0)] * padding + result

    while number > 0:
        remainder = number % len(alphabet)
        result.append(alphabet[remainder])
        number //= len(alphabet)

    return ''.join(result[::-1])

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not 0 <= number < len(alphabet):
        raise ValueError("Number must be between 0 and the length of the alphabet-1")

    if padding is not None and padding < len(str(number)):
        number = str(number).zfill(padding)

    return ''.join(alphabet[int(digit)] for digit in number)

