    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    if not isinstance(flow_params, dict):
        raise ValueError("Parameter 'flow_params' must be a dictionary")

    if not isinstance(register_number, int):
        raise ValueError("Parameter 'register_number' must be an integer")

    if not isinstance(register_value, str):
        raise ValueError("Parameter 'register_value' must be a string")

    if register_number not in flow_params:
        raise ValueError("Register number does not exist in flow params")

    if not flow_params[register_number].get(register_value):
        raise ValueError(f"Value '{register_value}' does not exist in register {register_number}")

    flow_params[register_number] = {**flow_params[register_number], register_value: None}

