    alphabet_mapping = dict(zip(alphabet, range(len(alphabet))))
    result = 0
    for char in reversed(string):
        if char not in alphabet_mapping:
            raise ValueError(f"Invalid character in string '{string}': {char}")
        result = result * len(alphabet) + alphabet_mapping[char]
    return result

def string_to_int(string: str, alphabet: List[str]) -> int:
    if not string or not alphabet:
        raise ValueError("Input string or alphabet cannot be empty")

    result = 0
    exponent = 0

    for char in reversed(string):
        match char in alphabet:
            if char not in alphabet:
                raise ValueError(f"Character '{char}' is not in the alphabet")
            index = alphabet.index(char)
            result += index * (len(alphabet) ** exponent)
            exponent += 1
        else:
            raise ValueError(f"Character '{char}' is not a valid character in the alphabet")

    return result

