import requests

def get_repo_archive(url: str, destination_path: Path) -> Path:
    import subprocess
    try:
        response = requests.get(url)
        response.raise_for_status()
        with open(destination_path, 'wb') as file:
            file.write(response.content)

        # Use the appropriate command to extract the .tar.gz file
        subprocess.run(['tar', '-xzf', destination_path.name, '-C', destination_path], check=True)

        return destination_path
    except requests.RequestException as e:
        raise Exception(f"Failed to download the archive: {e}")
    except subprocess.CalledProcessError as e:
        raise Exception(f"Failed to extract the archive: {e}")
    except FileNotFoundError as e:
        raise Exception(f"Destination directory does not exist: {e}")
    except Exception as e:
        raise Exception(f"An unexpected error occurred: {e}")

