import re

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import os

    if platform == 'this':
        platform = os.name.lower()

    regex = r"""
        (?:                    # Non-capturing group
            (?:[^\s'"`=]+)      # Non-alphanumeric character, including non-word characters
            | "\([^"]*"|'([^']*)'|
            (?:,|;|\))            # Commas, semicolons, or parentheses
        )+
    """
    if platform == 'posix':
        regex += r"""|"""
        regex += r"""(?:[^\w'"`=]+[^\s"']+)"""
        regex += r"""|"""
        regex += r"""((?: & )?[a-zA-Z_][a-zA-Z0-9_]*)"""
    elif platform == 'windows':
        regex += r"""|"""
        regex += r"""((?: \& )?[a-zA-Z_][a-zA-Z0-9_]*)"""

    # Strip off all the quotes
    if regex.startswith(r'"') and regex.endswith(r"'"):
        regex = regex.strip(r'"\'')
    elif regex.startswith(r"'") and regex.endswith(r'"'):
        regex = regex.strip(r'"\'')
    elif regex.startswith(r'"') or regex.endswith(r"'"):
        regex = regex.strip(r'"\'')

    return re.split(regex, s)

