def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader
    """
    if roots is None:
        roots = set()

    try:
        for child in graph.subjects(predicate=prop):
            for parent in graph.objects(subject=child, predicate=prop):
                roots.add(parent)
    except Exception as e:
        print(f"An error occurred: {e}")

    return roots

def find_roots(graph: rdflib.Graph, prop: rdflib.URIRef, roots: Optional[set] = None) -> set:
    if graph is None:
        raise ValueError("Graph cannot be None")
    if prop is None or not isinstance(prop, rdflib.URIRef):
        raise ValueError("Property must be a URIRef")

    # Initialize Roots if they are not provided
    if roots is None:
        roots = set()

    # Retrieve all nodes with the given property (subClassOf for RDFS, broader for SKOS)
    for s, p, o in graph.triples((None, prop, None)):
        roots.add(o)

    # Recursively find roots for each child node
    visited = set()
    for root in roots:
        if root not in visited:
            roots.update(find_roots(graph, prop, visited))
            visited.add(root)

    return roots

