        raise ValueError("Invalid input for graph or property")

    if roots is None:
        roots = set()

    previously_visited = set()
    pending_nodes = {node for node in graph.subjects(predicate=prop)}  # Starting from properties that point to uris

    while pending_nodes:
        current_node = pending_nodes.pop()
        if current_node not in previously_visited:
            previously_visited.add(current_node)
            ancestor Nodes = {ancestor for ancestor in graph.objects(subject=current_node, predicate=prop)}
            roots.update(ancestor_nodes)
            pending_nodes.update(ancestor_nodes)

    return roots

