from rdflib import Graph, URIRef, RDF

def find_roots(
    graph: Graph, prop: URIRef, roots: Optional[set[URIRef]] = None
) -> set[URIRef]:
    def dfs(node: URIRef, visited: set[URIRef]):
        if node in visited:
            return
        visited.add(node)
        for child in graph.objects(node, prop):
            dfs(child, visited)

    roots = [] if roots is None else list(roots)
    visited = set()
    while roots:
       root = roots.pop(0)
        dfs(root, visited)
        roots += list(visited)
        visited.clear()

    return set(root for root in visited)

