from collections import defaultdict

class LRU_Cache:
    def __init__(self, capacity: int):
        self.cache = defaultdict(int)
        self.used_items = []
        self.capacity = capacity

    def get(self, key: int) -> int:
        if key in self.cache:
            self.used_items.remove(key)
            self.used_items.append(key)
            return self.cache[key]
        return -1

    def put(self, key: int, value: int) -> None:
        if key in self.cache:
            self.used_items.remove(key)
        if len(self.used_items) == self.capacity:
            least_frequent = min(self.cache, key=self.cache.get)
            del self.cache[least_frequent]
            del self.used_items[self.used_items.index(least_frequent)]
        self.cache[key] = value
        self.used_items.append(key)

    def popitem(self) -> tuple[int, int] or None:
        if not self.used_items:
            return None

        least_frequent = min(self.cache, key=self.cache.get)
        value = self.cache.pop(least_frequent)
        self.used_items.remove(least_frequent)
        return least_frequent, value

