def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    import subprocess
    import sys

    # Validate input parameters
    if not vars_dict:
        raise ValueError("vars_dict must not be None or empty")
    if not cli_args:
        raise ValueError("cli_args must not be None or empty")
    if not ir_workspace:
        raise ValueError("ir_workspace must not be None")
    if not ir_plugin:
        raise ValueError("ir_plugin must not be None")

    # Construct Ansible command with extra-vars
    ansible_cmd = ["ansible-playbook"]
    for arg in cli_args:
        ansible_cmd.append(arg)
    if vars_dict:
        ansible_cmd.extend(["--extra-vars", f"{vars_dict}"])

    # Run Ansible command and capture output
    try:
        result = subprocess.run(ansible_cmd, capture_output=True, text=True, check=True)
        return result.stdout
    except subprocess.CalledProcessError as e:
        # Handle errors like invalid playbook, permission issues, etc.
        if e.stderr:
            return f"Error: {e.stderr}"
        else:
            return f"Error: {e.stdout}"
    except Exception as e:
        return f"Internal error: {str(e)}"

