import os

def strip_root(path, root):
    if not os.path.isabs(path) or os.path.isfile(path):
        raise ValueError("Path must be an absolute directory path")

    normalized_path = os.path.normpath(path)
    if not normalized_path.startswith(root):
        raise ValueError("Path does not start with the specified root")

    relative_path = normalized_path[len(root):].strip(os.sep)

    return relative_path
